package nl.smartstreamlabs.sbwdroneconfig;
import java.io.*;import java.nio.file.*;import java.util.*;
/** One machine joins the SERVER queue. No independent unbounded tile ticker. */
public final class DwfMachine implements DwfWorkBudget.Job{
 public final DwfBlockEntity block;public final DwfStorage input,output;public final DwfProduction<DwfItemKey>production=new DwfProduction<>();private final DwfServer.Context server;
 private final DwfIo.Load load;private DwfPlanner planner;private DwfRecipes.Entry selected;private DwfProduction.Saved pending;private boolean ready,failed,closed,dirty;private long lastWorkTick=Long.MIN_VALUE;private long generation,planGeneration,attemptGeneration=Long.MIN_VALUE,saveAt,visualAt,revision;private boolean lastCreativeAuthorization;private UUID creativeActor;private String error="Loading storage";private Set<net.minecraft.world.item.Item>dependencies=Set.of();
 public DwfMachine(DwfBlockEntity block,DwfServer.Context server){this.block=block;this.server=server;input=new DwfStorage(DwfConfig.INPUT_ITEMS.get(),DwfConfig.INPUT_VARIANTS.get(),this::inputChanged,server.variants);output=new DwfStorage(DwfConfig.OUTPUT_ITEMS.get(),DwfConfig.OUTPUT_VARIANTS.get(),items->changed(),server.variants);input.useBudget(server.work);output.useBudget(server.work);input.beginLoad();output.beginLoad();load=server.disk.load(block.id(),path());server.work.add(this);server.machines.add(this);}
 private Path path(){return server.directory.resolve(block.id()+".dwf");}
 private void changed(){dirty=true;revision++;block.setChanged();}
 private void inputChanged(Set<net.minecraft.world.item.Item>items){changed();if(selected==null)return;boolean relevant=dependencies.isEmpty()||items.stream().anyMatch(dependencies::contains);if(relevant)generation++;}
 DwfServer.Context serverContext(){return server;}
 public boolean creativeMode(){return creativeActor!=null&&creativeAuthorized();}
 private boolean creativeAuthorized(){var player=creativeActor==null?null:server.server.getPlayerList().getPlayer(creativeActor);return player!=null&&player.isCreative();}
 public boolean ready(){return ready&&!closed&&!failed;}public String error(){return error;}public long revision(){return revision;}
 public void catalogChanged(){var saved=order();if(planner!=null){planner.cancel();server.work.remove(planner);planner=null;}pending=saved;selected=server.catalog().byId().get(net.minecraft.resources.ResourceLocation.tryParse(saved.recipe()));production.restore(saved,null);generation++;attemptGeneration=Long.MIN_VALUE;dependencies=Set.of();changed();block.visualChanged();}
 public String presentationState(){if(failed)return "ERROR";if(!ready())return "LOADING";if(creativeActor!=null&&order().enabled()&&!creativeAuthorized())return "CREATIVE_PLAYER_REQUIRED";if(production.recipe()!=null)return production.state().name();var saved=order();if(selected==null)return saved.recipe().isEmpty()?"OFF":"ERROR";if(!saved.enabled())return "IDLE";if(saved.paused())return "PAUSED";if(error.equals("Missing materials"))return "MISSING_INPUT";return error.isEmpty()?"LOADING":"ERROR";}
 public DwfRecipes.Entry selected(){return selected;}public DwfProduction.Saved order(){return pending!=null?pending:production.save();}
 public DwfStorage storage(int chest){return chest==0?input:output;}
 public DwfWorkBudget.Kind kind(){if(creativeActor!=null&&!creativeAuthorized()&&ready)return DwfWorkBudget.Kind.RECIPE;if(!ready)return DwfWorkBudget.Kind.PERSISTENCE;var r=production.recipe();return r!=null&&production.progress()>=r.ticks()?DwfWorkBudget.Kind.COMPLETION:DwfWorkBudget.Kind.RECIPE;}
 public boolean available(){if(!ready)return load.failure!=null||load.hasRecords()||load.complete&&input.indexAvailable()&&output.indexAvailable();return kind()!=DwfWorkBudget.Kind.RECIPE||lastWorkTick!=server.server.overworld().getGameTime();}
 public boolean step(){
  if(closed)return false;if(ready){input.flush();output.flush();}long now=server.server.overworld().getGameTime();
  if(!ready){if(failed)return false;try{var left=new ArrayList<DwfIo.Record>();var right=new ArrayList<DwfIo.Record>();for(int i=0;i<16;i++){var record=load.poll();if(record==null)break;(record.chest()==0?left:right).add(record);}input.restoreBatch(left);output.restoreBatch(right);input.flush();output.flush();if(load.failure!=null)throw new IOException("Cannot load fabricator storage",load.failure);if(load.drained()){input.prepareIndex(server.calculations);output.prepareIndex(server.calculations);if(input.adoptIndex()&&output.adoptIndex()){if(load.state!=null)restore(load.state);ready=true;error="";dirty=false;saveAt=now+1200;block.visualChanged();}}}catch(Exception ex){load.cancel();failed=true;error=ex.getMessage();SbwDroneRangeConfig.LOGGER.error("DWF storage {} remains locked; no contents discarded",block.id(),ex);}return !failed;}
  
  lastWorkTick=now;
  if(creativeActor!=null){
   boolean authorized=creativeAuthorized();if(authorized!=lastCreativeAuthorization){lastCreativeAuthorization=authorized;block.visualChanged();}
   if(!authorized){production.unload();if(dirty&&now>=saveAt){checkpoint();saveAt=now+1200;}return true;}
   if(selected!=null&&production.recipe()==null){var saved=pending!=null?pending:production.save();var r=new DwfProduction.Recipe<DwfItemKey>(selected.id().toString(),Map.of(),server.variants.intern(selected.product()),selected.output().getCount(),productionTicks(),true);production.restore(saved,r);pending=null;error="";}
  }
  if(selected!=null&&creativeActor==null&&planner==null&&generation!=attemptGeneration){var current=production.recipe();boolean valid=current!=null; if(current!=null)for(var e:current.ingredients().entrySet())if(input.counts.count(e.getKey())<e.getValue()){valid=false;break;}if(!valid){if(pending==null)pending=production.save();production.restore(pending,null);plan();}else attemptGeneration=generation;}
  if(planner!=null&&planner.complete()){server.work.remove(planner);
   try{dependencies=Set.copyOf(planner.dependencies());var ingredients=planner.result();if(ingredients!=null){boolean valid=true;for(var cost:ingredients.entrySet())if(input.counts.count(cost.getKey())<cost.getValue()){valid=false;break;}if(!valid){planner=null;attemptGeneration=Long.MIN_VALUE;return true;}attemptGeneration=generation;var r=new DwfProduction.Recipe<DwfItemKey>(selected.id().toString(),ingredients,server.variants.intern(selected.product()),selected.output().getCount(),productionTicks());var saved=pending!=null?pending:production.save();if(saved.recipe().isEmpty())production.select(r);else production.restore(saved,r);pending=null;error="";}else error="Missing materials";}catch(RuntimeException ex){error="Recipe preparation failed";SbwDroneRangeConfig.LOGGER.error("DWF planning failed",ex);}planner=null;block.visualChanged();
  }
  var before=production.state();boolean done=production.visit(now,input.counts,output.counts,kind()==DwfWorkBudget.Kind.COMPLETION,generation);if(done){input.flush();output.flush();changed();block.getLevel().playSound(null,block.getBlockPos(),net.minecraft.sounds.SoundEvents.NOTE_BLOCK_PLING.value(),net.minecraft.sounds.SoundSource.BLOCKS,(float)(DwfConfig.SOUND_VOLUME.get()*.35),1);}
  if(before!=production.state())block.visualChanged();if(now>=visualAt){visualAt=now+10;if(production.state()==DwfProduction.State.RUNNING)block.visualChanged();}
  if(dirty&&now>=saveAt){checkpoint();saveAt=now+1200;}var diskFailure=server.disk.failure(block.id());if(diskFailure!=null){error="Storage save failed; stop and check server log";production.pause();}
  return true;
 }
 private void plan(){attemptGeneration=generation;planner=new DwfPlanner(selected,input,server.calculations);planGeneration=generation;server.work.add(planner);}
 public int productionTicks(){return selected==null?1:Math.max(1,(int)Math.ceil(selected.ticks()/DwfConfig.PRODUCTION_SPEED.get()));}
 public void select(String id){var entry=server.catalog().byId().get(net.minecraft.resources.ResourceLocation.tryParse(id));if(entry==null)throw new IllegalArgumentException("Unknown assembly recipe");if(selected!=null&&selected.id().equals(entry.id()))return;creativeActor=null;if(planner!=null){planner.cancel();server.work.remove(planner);}selected=entry;error="";production.stop();pending=new DwfProduction.Saved(id,0,false,false,false,0);production.restore(pending,null);planner=null;generation++;changed();block.visualChanged();}
 public void start(long amount,boolean continuous){start(amount,continuous,null);}
 public void start(long amount,boolean continuous,net.minecraft.server.level.ServerPlayer actor){if(selected==null)throw new IllegalStateException("Select a product first");UUID next=actor!=null&&actor.isCreative()?actor.getUUID():null;if(!Objects.equals(creativeActor,next)){if(planner!=null){planner.cancel();server.work.remove(planner);planner=null;}var saved=order();pending=saved;production.restore(saved,null);creativeActor=next;attemptGeneration=Long.MIN_VALUE;generation++;}if(production.recipe()!=null)production.start(amount,continuous);else pending=new DwfProduction.Saved(selected.id().toString(),amount,continuous,true,false,0);changed();block.visualChanged();}
 public void action(int action){if(pending!=null){var s=pending;pending=new DwfProduction.Saved(s.recipe(),s.remaining(),s.continuous(),action==3?false:s.enabled(),action==1?true:action==2?false:s.paused(),action==3?0:s.progress());}if(action==1)production.pause();else if(action==2)production.resume();else if(action==3){production.stop();if(pending!=null)pending=new DwfProduction.Saved(pending.recipe(),0,false,false,false,0);}changed();block.visualChanged();}
 private void restore(byte[]data)throws IOException{try(var in=new DataInputStream(new ByteArrayInputStream(data))){int version=in.readInt();if(version!=1&&version!=2)throw new IOException("Unknown machine state");pending=new DwfProduction.Saved(in.readUTF(),in.readLong(),in.readBoolean(),in.readBoolean(),in.readBoolean(),in.readLong());creativeActor=version>=2&&in.readBoolean()?new UUID(in.readLong(),in.readLong()):null;if(in.read()!=-1)throw new IOException("Trailing machine state");production.restore(pending,null);selected=server.catalog().byId().get(net.minecraft.resources.ResourceLocation.tryParse(pending.recipe()));}}
 private byte[]state(){try{var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){var s=pending!=null?pending:production.save();out.writeInt(2);out.writeUTF(s.recipe());out.writeLong(s.remaining());out.writeBoolean(s.continuous());out.writeBoolean(s.enabled());out.writeBoolean(s.paused());out.writeLong(s.progress());out.writeBoolean(creativeActor!=null);if(creativeActor!=null){out.writeLong(creativeActor.getMostSignificantBits());out.writeLong(creativeActor.getLeastSignificantBits());}}return bytes.toByteArray();}catch(IOException impossible){throw new UncheckedIOException(impossible);}}
 public void checkpoint(){if(!ready||failed)return;server.disk.save(block.id(),path(),input.counts.snapshot(),output.counts.snapshot(),state());dirty=false;}
 public void close(){if(closed)return;checkpoint();closed=true;input.cancelLoad();output.cancelLoad();server.machines.remove(this);production.unload();load.cancel();server.work.remove(this);if(planner!=null){planner.cancel();server.work.remove(planner);}}
}
